def render_table(data: Any, style: str = "rounded") -> str:
    """Render a decoded response as a table.

    A list of objects becomes one row per object, with a column for every key
    any of them has, in first-seen order. A single object becomes a key/value
    table and a list of scalars a single-column one. A nested value is shown
    as compact JSON in its cell, so nothing the response holds is dropped.

    Args:
        data: The decoded JSON of the response
        style: Borders of the table, a key of the known styles

    Returns:
        The rendered table, without a trailing newline
    """
