def _draw(columns: list[str], rows: list[list[str]], style: dict[str, Any]) -> str:
    """Lay out header and rows in equal-width columns with the style's borders."""
    widths = [
        max(len(column), *(len(row[i]) for row in rows))
        for i, column in enumerate(columns)
    ]
    left, between, right = style["row"]
    lines: list[str] = []

    def rule(spec: Rule) -> None:
        if spec is not None:
            lead, fill, joint, end = spec
            lines.append(lead + joint.join(fill * w for w in widths) + end)

    def row(cells: list[str]) -> None:
        padded = [cell.ljust(w) for cell, w in zip(cells, widths)]
        lines.append((left + between.join(padded) + right).rstrip())

    rule(style["top"])
    row(columns)
    rule(style["header"])
    for cells in rows:
        row(cells)
    rule(style["bottom"])
    return "\n".join(lines)
